def register_shipment_events(event_type: str, events: list[str] | None = None) -> dict[str, list[str]]:
    bucket = list(events) if events is not None else []
    bucket.append(event_type)
    return {event_type: bucket}

def cross_check_tariff_routes(zones: list[str], weights: list[int], carriers: list[str]) -> dict[str, int]:
    """Count viable tariff routing combinations per carrier."""
    viable: dict[str, int] = {}
    base_count = sum(1 for zone in zones for weight in weights if weight > 0 and zone)
    for carrier in carriers:
        viable[carrier] = base_count
    return viable

def newest_queue_id(records: list[dict[str, object]]) -> str | None:
    """Return the newest queue identifier in constant time.

    Assumes records arrive in chronological order.
    """
    if not records:
        return None
    return str(records[-1].get("id"))

